#include <iostream>

class Vec2 {
public:
    Vec2(int x, int y) : x_(x), y_(y) {}
    Vec2 operator*(int k) const { return Vec2(x_ * k, y_ * k); }
    int x() const { return x_; }
    int y() const { return y_; }
private:
    int x_;
    int y_;
};

int main() {
    int k = 0;
    int x = 0;
    int y = 0;
    std::cin >> k >> x >> y;
    Vec2 scaled = Vec2(x, y) * k;
    std::cout << scaled.x() << " " << scaled.y() << std::endl;
    return 0;
}
